--liquibase formatted sql

--changeset pixels:furniture-seed-posture-metadata-0046 context:development
create temporary table posture_review(id bigint primary key,name text not null,status text not null,confidence text not null,source text not null,reason text not null,previous_allow_sit boolean not null,previous_allow_lay boolean not null) on commit drop;
;
create temporary table posture_guard(definitions_match boolean constraint posture_review_definitions_must_match check(definitions_match),manual_metadata_free boolean constraint posture_review_must_not_override_manual_metadata check(manual_metadata_free)) on commit drop;
update furniture_definitions definition set allow_sit=definition.allow_sit or review.status='sit',allow_lay=definition.allow_lay or review.status='lay',metadata=jsonb_set(definition.metadata,'{posture}',jsonb_build_object('audit_id','pixelados-2026-07-25','version',1,'source',review.source,'status',review.status,'confidence',review.confidence,'reason',review.reason,'strategy',case when review.status='none' then 'none' else 'derived_footprint' end,'manual_override',true),true),updated_at=now(),version=definition.version+1 from posture_review review where definition.id=review.id;
update furniture_definitions definition set metadata=jsonb_set(definition.metadata,'{posture}',jsonb_build_object('audit_id','pixelados-2026-07-25','version',1,'source',case when jsonb_exists(definition.metadata,'slots') then 'explicit_slots' else 'definition_flags' end,'status',case when definition.allow_sit and definition.allow_lay then 'sit_lay' when definition.allow_lay then 'lay' when definition.allow_sit then 'sit' else 'none' end,'confidence',case when jsonb_exists(definition.metadata,'slots') then 'high' when definition.allow_sit or definition.allow_lay then 'medium' else 'unclassified' end,'strategy',case when jsonb_exists(definition.metadata,'slots') then 'explicit_slots' when definition.allow_sit or definition.allow_lay then 'derived_footprint' else 'none' end,'manual_override',false),true),updated_at=now(),version=definition.version+1 where definition.deleted_at is null and not jsonb_exists(definition.metadata,'posture');
