insert into posture_guard select (select count(*) from posture_review review join furniture_definitions definition on definition.id=review.id and definition.name=review.name and definition.deleted_at is null)=(select count(*) from posture_review),not exists(select 1 from posture_review review join furniture_definitions definition on definition.id=review.id where jsonb_exists(definition.metadata,'slots') or coalesce((definition.metadata->'posture'->>'manual_override')::boolean,false));
